"""Minimal OpenFOAM ASCII file I/O (headers, points, fields)."""
from __future__ import annotations

import re
from pathlib import Path

import numpy as np

BANNER = "/*--------------------------------*- C++ -*----------------------------------*\\\n" \
         "  generated by windsurrogate\n" \
         "\\*---------------------------------------------------------------------------*/\n"


def header(cls: str, obj: str, location: str | None = None) -> str:
    loc = f'    location    "{location}";\n' if location else ""
    return (BANNER + "FoamFile\n{\n    version     2.0;\n    format      ascii;\n"
            f"    class       {cls};\n{loc}    object      {obj};\n}}\n\n")


def write_dict(path: Path, obj: str, body: str, location: str | None = None) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(header("dictionary", obj, location) + body.strip() + "\n")


def write_points(path: Path, pts: np.ndarray) -> None:
    pts = np.asarray(pts, dtype=np.float64).reshape(-1, 3)
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w") as f:
        f.write(header("vectorField", "points", "constant/polyMesh"))
        f.write(f"{len(pts)}\n(\n")
        np.savetxt(f, pts, fmt="(%.4f %.4f %.4f)")
        f.write(")\n")


def nonuniform(values: np.ndarray) -> str:
    """'nonuniform List<...> N (...)' text for an internalField or patch value."""
    v = np.asarray(values, dtype=np.float64)
    import io
    buf = io.StringIO()
    if v.ndim == 2 and v.shape[1] == 3:
        buf.write(f"nonuniform List<vector>\n{len(v)}\n(\n")
        np.savetxt(buf, v, fmt="(%.6g %.6g %.6g)")
    else:
        v = v.reshape(-1)
        buf.write(f"nonuniform List<scalar>\n{len(v)}\n(\n")
        np.savetxt(buf, v, fmt="%.6g")
    buf.write(")")
    return buf.getvalue()


def write_field(path: Path, cls: str, name: str, dims: str, internal: str, boundary: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w") as f:
        f.write(header(cls, name, "0"))
        f.write(f"dimensions      {dims};\n\ninternalField   {internal};\n\n")
        f.write("boundaryField\n{\n" + boundary.rstrip() + "\n}\n")


_NUM = re.compile(rb"internalField\s+(uniform|nonuniform)")


def read_internal_field(path: Path, n_cells: int) -> np.ndarray:
    """Read the internalField of an ASCII volScalarField/volVectorField."""
    raw = Path(path).read_bytes()
    m = _NUM.search(raw)
    if m is None:
        raise ValueError(f"no internalField in {path}")
    pos = m.end()
    if m.group(1) == b"uniform":
        end = raw.index(b";", pos)
        txt = raw[pos:end].replace(b"(", b" ").replace(b")", b" ")
        val = np.array(txt.split(), dtype=np.float64)
        return np.tile(val, (n_cells, 1)).squeeze()
    # nonuniform List<type> N ( ... )
    m2 = re.compile(rb"List<(\w+)>\s*(\d+)\s*\(").search(raw, pos)
    kind, count = m2.group(1), int(m2.group(2))
    start = m2.end()
    end = raw.index(b"\n)", start)
    body = raw[start:end]
    if kind == b"vector":
        body = body.replace(b"(", b" ").replace(b")", b" ")
        arr = np.array(body.split(), dtype=np.float64).reshape(count, 3)
    else:
        arr = np.array(body.split(), dtype=np.float64)
    if count != n_cells:
        raise ValueError(f"{path}: {count} values, expected {n_cells}")
    return arr


def latest_time_dir(case: Path) -> Path | None:
    times = []
    for p in Path(case).iterdir():
        if p.is_dir():
            try:
                times.append((float(p.name), p))
            except ValueError:
                pass
    times.sort()
    return times[-1][1] if times and times[-1][0] > 0 else None
